    // Pendulum model/measurement for Section 4 (EKF vs UKF): state [theta, omega], NONLINEAR dynamics
    // theta'=theta+omega*dt, omega'=omega-(g/L)sin(theta)*dt; NONLINEAR measurement h=sin(theta). Same
    // dynamics as KalmanTests.float.cs's own pendulum fixture, redeclared here (a separate assembly).
    public struct PendulumModelFloat : IfloatKFModel
    {
        public float dt;
        public float gOverL;

        public void F(in floatN x, in floatN u, ref floatN xNext)
        {
            float th = x[0], om = x[1];
            xNext[0] = th + om * dt;
            xNext[1] = om - gOverL * math.sin(th) * dt;
        }

        public void JacobianF(in floatN x, in floatN u, ref floatMxN J)
        {
            float th = x[0];
            J[0, 0] = (float)1; J[0, 1] = dt;
            J[1, 0] = -gOverL * math.cos(th) * dt; J[1, 1] = (float)1;
        }
    }

    public struct PendulumMeasFloat : IfloatKFMeasurement
    {
        public void H(in floatN x, ref floatN z) => z[0] = math.sin(x[0]);

        public void JacobianH(in floatN x, ref floatMxN J)
        {
            J[0, 0] = math.cos(x[0]); J[0, 1] = (float)0;
        }
    }

    // Synthetic drone-scale nonlinear model for Section 4's n=12 row: a ring of n coupled damped
    // oscillators, xNext[i] = a*x[i] + b*sin(x[(i+1)%n]) -- smooth, and contractive REGARDLESS of state
    // magnitude (sin is bounded in [-1,1], so |a|<1 alone bounds every orbit), unlike the pendulum's
    // forward-Euler drift. Exists only to exercise ekfPredict/ukfPredict's Jacobian/sigma-point cost at
    // n=12, not to model any real system.
    public struct RingModelFloat : IfloatKFModel
    {
        public int n;
        public float a;
        public float b;

        public void F(in floatN x, in floatN u, ref floatN xNext)
        {
            for (int i = 0; i < n; i++)
            {
                int j = (i + 1) % n;
                xNext[i] = a * x[i] + b * math.sin(x[j]);
            }
        }

        public void JacobianF(in floatN x, in floatN u, ref floatMxN J)
        {
            for (int i = 0; i < n; i++)
                for (int k = 0; k < n; k++)
                    J[i, k] = (float)0;
            for (int i = 0; i < n; i++)
            {
                int j = (i + 1) % n;
                J[i, i] += a;
                J[i, j] += b * math.cos(x[j]);
            }
        }
    }

    // Measurement for RingModelFloat: picks m components evenly spread through the ring
    // (indices 0, stride, 2*stride, ...) through sin(), so the Jacobian stays a simple diagonal-in-
    // the-picked-columns pattern regardless of m/n.
    public struct RingMeasFloat : IfloatKFMeasurement
    {
        public int m;
        public int stride;

        public void H(in floatN x, ref floatN z)
        {
            for (int j = 0; j < m; j++) z[j] = math.sin(x[j * stride]);
        }

        public void JacobianH(in floatN x, ref floatMxN J)
        {
            int n = J.N_Cols;
            for (int i = 0; i < m; i++)
                for (int k = 0; k < n; k++)
                    J[i, k] = (float)0;
            for (int j = 0; j < m; j++)
                J[j, j * stride] = math.cos(x[j * stride]);
        }
    }

